package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ScienceLiveExamChemAtomBank2 {
  private const val T = "පරමාණුක ව්‍යුහය, ආවර්තිතා වගුව, බන්ධන හා ද්‍රාවණ"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String = "පරමාණුක ව්‍යුහය, ආවර්තිතා වගුව හා ද්‍රාවණ පිළිබඳ නිවැරදි කරුණකි."
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("පරමාණුවක ඉලෙක්ට්‍රෝන ගමන් කරන නිශ්චිත ශක්ති මට්ටම් පවතින බව පළමුව යෝජනා කළ විද්‍යාඥයා කවුද?", "නීල්ස් බෝර්", "ජෝන් ඩෝල්ටන්", "ජේ. ජේ. තොම්සන්", "ඇවගාඩ්‍රෝ", "බෝර් ආකෘතිය මගින් කවච තුළ ඉලෙක්ට්‍රෝන ස්ථානගත වන ආකාරය පැහැදිලි කෙරිණි."),
    q("ඉලෙක්ට්‍රෝනයක සාපේක්ෂ ආරෝපණය සහ සාපේක්ෂ ස්කන්ධය පිළිවෙළින් කෙබඳුද?", "ආරෝපණය -1, ස්කන්ධය නොසැලකිය හැකි තරම් කුඩා (≈ 1/1840)", "ආරෝපණය +1, ස්කන්ධය 1", "ආරෝපණය 0, ස්කන්ධය 1", "ආරෝපණය -1, ස්කන්ධය 1", "ප්‍රෝටෝනයක් හා නියුට්‍රෝනයක් හා සසඳන විට ඉලෙක්ට්‍රෝනය ඉතා සැහැල්ලුය."),
    q("සෝඩියම් අයනයේ (Na⁺) අඩංගු ඉලෙක්ට්‍රෝන සංඛ්‍යාව කීයද? (Na හි Z = 11)", "10", "11", "12", "23", "Na පරමාණුව ඉලෙක්ට්‍රෝනයක් පිට කර Na⁺ වන විට ඉලෙක්ට්‍රෝන 10 ක් ඉතිරි වේ."),
    q("ක්ලෝරයිඩ් අයනයේ (Cl⁻) ප්‍රෝටෝන හා ඉලෙක්ට්‍රෝන සංඛ්‍යා පිළිවෙළින් කීයද? (Cl හි Z = 17)", "ප්‍රෝටෝන 17, ඉලෙක්ට්‍රෝන 18", "ප්‍රෝටෝන 18, ඉලෙක්ට්‍රෝන 17", "ප්‍රෝටෝන 17, ඉලෙක්ට්‍රෝන 17", "ප්‍රෝටෝන 16, ඉලෙක්ට්‍රෝන 18", "Cl පරමාණුව ඉලෙක්ට්‍රෝනයක් ලබාගෙන Cl⁻ වේ; ප්‍රෝටෝන ගණන වෙනස් නොවේ."),
    q("Mg²⁺ (Z=12) සහ F⁻ (Z=9) යන අයන දෙකෙහි සමාන වන්නේ කුමක්ද?", "ඉලෙක්ට්‍රෝන සංඛ්‍යාව (10 බැගින්)", "ප්‍රෝටෝන සංඛ්‍යාව", "න්‍යෂ්ටික ආරෝපණය", "ස්කන්ධ ක්‍රමාංකය", "සමාන ඉලෙක්ට්‍රෝන සංඛ්‍යාවක් ඇති අයන හා පරමාණු සම-ඉලෙක්ට්‍රොනික (Isoelectronic) වේ."),
    q("කැල්සියම් (Z = 20) පරමාණුවේ ඉලෙක්ට්‍රෝන වින්‍යාසය හා එය අයත් වන කාණ්ඩය කුමක්ද?", "2, 8, 8, 2 — II කාණ්ඩය", "2, 8, 10 — VIII කාණ්ඩය", "2, 8, 2 — II කාණ්ඩය", "2, 8, 8, 1 — I කාණ්ඩය", "කැල්සියම් 4 වන ආවර්තයේ II කාණ්ඩයේ පිහිටි ක්ෂාරීය පාංශු ලෝහයකි."),
    q("නයිට්‍රජන් (Z = 7) සහ පොස්පරස් (Z = 15) ආවර්තිතා වගුවේ එකම කාණ්ඩයට අයත් වන්නේ ඇයි?", "දෙකෙහිම අවසන් කවචයේ ඉලෙක්ට්‍රෝන 5 බැගින් ඇති බැවින්", "දෙකම කාමර උෂ්ණත්වයේ වායු බැවින්", "කවච ගණන සමාන බැවින්", "නියුට්‍රෝන ගණන සමාන බැවින්", "N (2, 5) හා P (2, 8, 5) යන දෙකම V කාණ්ඩයට අයත් වේ."),
    q("3 වන ආවර්තයේ පිහිටි Na, Mg, Al යන ලෝහ අතුරින් වඩාත්ම ප්‍රබල ලෙස ජලය සමඟ ප්‍රතික්‍රියා කරන්නේ කවරෙක්ද?", "සෝඩියම් (Na)", "මැග්නීසියම් (Mg)", "ඇලුමිනියම් (Al)", "සියල්ලම එක හා සමානය", "ආවර්තය දිගේ දකුණට යත්ම ලෝහවල ප්‍රතික්‍රියාශීලීතාව අඩු වේ."),
    q("3 වන ආවර්තයේ මූලද්‍රව්‍ය සාදන ඔක්සයිඩ Na₂O සිට SO₃ දක්වා ගමන් කරන විට ආම්ලික/භාෂ්මික ස්වභාවයේ විචලනය කුමක්ද?", "ප්‍රබල භාෂ්මික සිට උභයගුණී හරහා ප්‍රබල ආම්ලික දක්වා වෙනස් වේ", "සියල්ලම ප්‍රබල අම්ල වේ", "ප්‍රබල ආම්ලික සිට භාෂ්මික දක්වා වෙනස් වේ", "සියල්ලම උදාසීන වේ", "Al₂O₃ උභයගුණී ඔක්සයිඩයක් වන අතර P₄O₁₀, SO₃, Cl₂O₇ ආම්ලික වේ."),
    q("අම්ල හා භෂ්ම යන දෙවර්ගය සමඟම ප්‍රතික්‍රියා කර ලවණ හා ජලය සාදන 3 වන ආවර්තයේ උභයගුණී ඔක්සයිඩය කුමක්ද?", "ඇලුමිනියම් ඔක්සයිඩ් (Al₂O₃)", "සෝඩියම් ඔක්සයිඩ් (Na₂O)", "සල්ෆර් ඩයොක්සයිඩ් (SO₂)", "මැග්නීසියම් ඔක්සයිඩ් (MgO)", "Al₂O₃ හි අර්ධ අයනික හා අර්ධ සහසංයුජ ලක්ෂණ මීට හේතු වේ."),
    q("ක්ෂාරීය පාංශු ලෝහ අයත් වන II කාණ්ඩයේ පහළට යන විට (Be → Mg → Ca) රසායනික සක්‍රීයතාවට සිදුවන්නේ කුමක්ද?", "සක්‍රීයතාව වැඩි වේ", "සක්‍රීයතාව අඩු වේ", "වෙනස් නොවේ", "අලෝහ බවට පත් වේ", "පරමාණුක අරය විශාල වන විට අවසන් කවචයේ ඉලෙක්ට්‍රෝන ඉවත් කිරීම පහසු වේ."),
    q("හැලජන කාණ්ඩයේ (F₂, Cl₂, Br₂, I₂) කාමර උෂ්ණත්වයේදී භෞතික අවස්ථා වෙනස් වන නිවැරදි පිළිවෙළ කුමක්ද?", "F₂ හා Cl₂ වායු, Br₂ ද්‍රව, I₂ ඝන", "සියල්ලම වායු", "F₂ ඝන, Cl₂ ද්‍රව, Br₂ වායු", "සියල්ලම ද්‍රව", "පහළට යත්ම අණුක ස්කන්ධය වැඩි වී අන්තර්-අණුක ආකර්ෂණ බල වැඩි වේ."),
    q("ක්ලෝරීන් ජලීය ද්‍රාවණයකට ක්ලෝරීන්වලට වඩා අඩු සක්‍රීයතාවක් ඇති බ්‍රෝමයිඩ් (KBr) එක් කළ විට සිදු වන්නේ කුමක්ද?", "Cl₂ විසින් Br⁻ විස්ථාපනය කර රතු-දුඹුරු Br₂ මුදා හැරීම", "කිසිදු ප්‍රතික්‍රියාවක් නොවීම", "ලෝහ පොටෑසියම් සෑදීම", "හයිඩ්‍රජන් වායුව පිට වීම", "වැඩි සක්‍රීය හැලජනය අඩු සක්‍රීය හැලජනය එහි ලවණයෙන් විස්ථාපනය කරයි."),
